import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import base64
from io import BytesIO
import json
import os

# Set style
sns.set_theme(style="whitegrid")
plt.rcParams['figure.figsize'] = (10, 6)

def fig_to_base64(fig):
    img = BytesIO()
    fig.savefig(img, format='png', bbox_inches='tight')
    img.seek(0)
    return base64.b64encode(img.getvalue()).decode('utf-8')

print("Loading data...")
df = pd.read_csv('/app/benchmark/data.csv')

# Data cleaning
df['price'] = pd.to_numeric(df['price'], errors='coerce')
df['reviews_per_month'] = df['reviews_per_month'].fillna(0)
df['minimum_nights'] = pd.to_numeric(df['minimum_nights'], errors='coerce')

cities = df['city'].unique()

print("Calculating KPIs...")
# KPIs by City
kpi_df = pd.DataFrame({'City': df['city'].unique()}).set_index('City')

# 1. Median Nightly Price
kpi_df['Median Price'] = df.dropna(subset=['price']).groupby('city')['price'].median()

# 2. Professional Host Share
kpi_df['Prof Host Share (%)'] = df.assign(is_prof=df['calculated_host_listings_count'] >= 5).groupby('city')['is_prof'].mean() * 100

# 3. Average Reviews per Month
kpi_df['Avg Reviews/Month'] = df.groupby('city')['reviews_per_month'].mean()

# 4. Mean Availability
kpi_df['Mean Availability'] = df.groupby('city')['availability_365'].mean()

# 5. Entire Home Share
kpi_df['Entire Home Share (%)'] = df.assign(is_entire=df['room_type'] == 'Entire home/apt').groupby('city')['is_entire'].mean() * 100

kpi_df = kpi_df.round(2)

# Generate Charts
charts = {}

print("Generating Charts...")
# 1. Total Listings by City
fig, ax = plt.subplots()
listing_counts = df['city'].value_counts().sort_values(ascending=True)
listing_counts.plot(kind='barh', color='skyblue', ax=ax)
ax.set_title('Total Listings by City')
ax.set_xlabel('Number of Listings')
charts['listings'] = fig_to_base64(fig)
plt.close(fig)

# 2. Median Price by City
fig, ax = plt.subplots()
median_prices = kpi_df['Median Price'].sort_values(ascending=True)
median_prices.plot(kind='barh', color='salmon', ax=ax)
ax.set_title('Median Nightly Price by City (USD)')
ax.set_xlabel('Price (USD)')
charts['median_price'] = fig_to_base64(fig)
plt.close(fig)

# 3. Price Distribution (Boxplot) by City (filtering outliers)
fig, ax = plt.subplots(figsize=(12, 8))
df_price = df.dropna(subset=['price'])
# Filter out top 5% extreme prices per city for better visualization
q95 = df_price.groupby('city')['price'].transform(lambda x: x.quantile(0.95))
df_price_filtered = df_price[df_price['price'] < q95]
sns.boxplot(data=df_price_filtered, x='price', y='city', order=median_prices.index[::-1], palette='Set2', ax=ax)
ax.set_title('Price Distribution by City (Excluding top 5% outliers)')
ax.set_xlabel('Price (USD)')
ax.set_ylabel('')
charts['price_dist'] = fig_to_base64(fig)
plt.close(fig)

# 4. Room Type Distribution
fig, ax = plt.subplots(figsize=(12, 6))
room_dist = df.groupby(['city', 'room_type']).size().unstack().fillna(0)
# Normalize to percentage
room_dist_pct = room_dist.div(room_dist.sum(axis=1), axis=0) * 100
room_dist_pct.sort_values('Entire home/apt').plot(kind='barh', stacked=True, colormap='viridis', ax=ax)
ax.set_title('Room Type Distribution by City (%)')
ax.set_xlabel('Percentage')
ax.legend(title='Room Type', bbox_to_anchor=(1.05, 1), loc='upper left')
charts['room_type'] = fig_to_base64(fig)
plt.close(fig)

# 5. Professional Host Share
fig, ax = plt.subplots()
prof_share = kpi_df['Prof Host Share (%)'].sort_values(ascending=True)
prof_share.plot(kind='barh', color='mediumpurple', ax=ax)
ax.set_title('Professional Host Share by City (%)')
ax.set_xlabel('% of Listings with >= 5 Listings by Host')
charts['prof_host'] = fig_to_base64(fig)
plt.close(fig)

# 6. Guest Demand (Reviews per month)
fig, ax = plt.subplots()
avg_reviews = kpi_df['Avg Reviews/Month'].sort_values(ascending=True)
avg_reviews.plot(kind='barh', color='coral', ax=ax)
ax.set_title('Average Reviews per Month by City')
ax.set_xlabel('Reviews per Month')
charts['reviews'] = fig_to_base64(fig)
plt.close(fig)

# 7. Availability & Minimum Nights
fig, ax = plt.subplots(1, 2, figsize=(14, 6))
kpi_df['Mean Availability'].sort_values().plot(kind='barh', color='lightgreen', ax=ax[0])
ax[0].set_title('Mean Availability (Days/Year)')
ax[0].set_xlabel('Days')

median_min_nights = df.groupby('city')['minimum_nights'].median().sort_values()
median_min_nights.plot(kind='barh', color='gold', ax=ax[1])
ax[1].set_title('Median Minimum Nights Required')
ax[1].set_xlabel('Nights')
plt.tight_layout()
charts['availability'] = fig_to_base64(fig)
plt.close(fig)

